// Generates lib/brand/geometry.brand.dart from the brand geometry the web uses
// (packages/ui/src/logo-geometry.json, traced from the reference artwork) and the wordmark
// letters (apps/client/public/brand/netfly-logo.v2.svg). test/brand_geometry_test.dart fails
// when the generated file is out of date.
//
// dart run tool/sync_brand.dart
import 'dart:convert';
import 'dart:io';

const geometrySource = '../../packages/ui/src/logo-geometry.json';
const logoSource = '../client/public/brand/netfly-logo.v2.svg';
const target = 'lib/brand/geometry.brand.dart';

String generate() {
  final g = jsonDecode(File(geometrySource).readAsStringSync()) as Map<String, dynamic>;
  final svg = File(logoSource).readAsStringSync();
  final letters = RegExp(r'<g fill="#FFFFFF" transform="translate\(([\d.]+) ([\d.]+)\)">(.*?)</g>').firstMatch(svg)!;
  final paths = RegExp(r'<path d="([^"]+)"/>').allMatches(letters.group(3)!).map((m) => m.group(1)!).toList();
  final viewBox = RegExp(r'viewBox="([^"]+)"').firstMatch(svg)!.group(1)!.split(' ').map(double.parse).toList();
  final mark = RegExp(r'<svg x="([-\d.]+)" y="([-\d.]+)" width="([\d.]+)" height="([\d.]+)"').firstMatch(svg)!;

  String layer(Map<String, dynamic> l) {
    final stops = (l['stops'] as List).map((s) => '(${(s as List)[0]}, ${s[1]})').join(', ');
    return l['type'] == 'radial'
        ? 'FoldLayer.radial(cx: ${l['cx']}, cy: ${l['cy']}, r: ${l['r']}, stops: [$stops])'
        : 'FoldLayer.linear(x1: ${l['x1']}, y1: ${l['y1']}, x2: ${l['x2']}, y2: ${l['y2']}, stops: [$stops])';
  }

  final folds = (g['folds'] as List)
      .map((f) {
        final m = f as Map<String, dynamic>;
        final layers = (m['layers'] as List).map((l) => layer(l as Map<String, dynamic>)).join(', ');
        return "  Fold('${m['d']}', [$layers]),";
      })
      .join('\n');

  return '''// GENERATED by tool/sync_brand.dart from packages/ui/src/logo-geometry.json and
// apps/client/public/brand/netfly-logo.v2.svg. Do not edit.
// ignore_for_file: require_trailing_commas

part of 'geometry.dart';

const markColor = Color(0xFF${(g['color'] as String).substring(1)});
const bandPath = '${g['band']}';
const centerLinePath = '${g['centerLine']}';
const bandWidth = ${g['bandWidth']};

const folds = <Fold>[
$folds
];

/// The wordmark: viewBox, the mark's box inside it, and the letters (white, translated).
const wordmarkViewBox = Rect.fromLTWH(${viewBox[0]}, ${viewBox[1]}, ${viewBox[2]}, ${viewBox[3]});
const wordmarkMarkBox = Rect.fromLTWH(${mark.group(1)}, ${mark.group(2)}, ${mark.group(3)}, ${mark.group(4)});
const wordmarkLettersOffset = Offset(${letters.group(1)}, ${letters.group(2)});
const wordmarkLetters = <String>[
${paths.map((p) => "  '$p',").join('\n')}
];
''';
}

/// The generated source as `dart format` leaves it (the repo's files are formatted).
String formatted(String source) {
  final tmp = Directory.systemTemp.createTempSync('netfly_brand');
  try {
    final file = File('${tmp.path}/geometry.brand.dart')..writeAsStringSync(source);
    final result = Process.runSync('dart', ['format', '--page-width=120', file.path]);
    if (result.exitCode != 0) throw StateError('dart format failed: ${result.stderr}');
    return file.readAsStringSync();
  } finally {
    tmp.deleteSync(recursive: true);
  }
}

void main(List<String> args) {
  final out = formatted(generate());
  if (args.contains('--check')) {
    final current = File(target).existsSync() ? File(target).readAsStringSync() : '';
    if (current != out) {
      stderr.writeln('$target is out of date: run `dart run tool/sync_brand.dart`.');
      exit(1);
    }
    return;
  }
  File(target).writeAsStringSync(out);
  stdout.writeln('wrote $target');
}
